def _helper_check_plan_invariants_guard(plan) -> object:
    """Extract workplan from plan or strategy. Returns None if neither exists."""
    workplan = getattr(plan, 'workplan', None)
    if not workplan:
        strategy = getattr(plan, 'strategy', None)
        if strategy:
            workplan = getattr(strategy, 'parallelisable_workplan', None)
    return workplan


def _helper_check_plan_invariants_collect_tasks(groups: list) -> list:
    """Collect all tasks from a list of groups."""
    tasks: list = []
    for group in groups:
        tasks.extend(getattr(group, 'tasks', []) or [])
    return tasks


def _helper_check_plan_invariants_loop(tasks: list, seen: set[str], violations: list[str]) -> None:
    """Check file path constraints on each task and record violations."""
    for task in tasks:
        fps = getattr(task, 'file_paths', None) or []
        if len(fps) != 1:
            violations.append(f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)")
        for fp in fps:
            if fp in seen:
                violations.append(f'file collision: {fp} in multiple tasks')
            seen.add(fp)"}
